using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Web.Script.Serialization;
namespace MonitorSlice {
static class VirtualTests {
 public static void CheckModes(){var displays=Displays.Virtual();if(displays.Count!=4)throw new Exception("가상 모니터 4개 확인 실패");var physical=Screen.AllScreens.Where(s=>!displays.Any(d=>d.Name==s.DeviceName)).ToArray();int checkedModes=0;foreach(var screen in physical)foreach(var area in new[]{screen.Bounds,new Rectangle(0,0,screen.Bounds.Height,screen.Bounds.Width)})foreach(var key in Layouts.Keys)foreach(var r in Layouts.Create(key)){var size=Layouts.Bounds(r,area,0).Size;Displays.Resolution(displays[r.Slot].Name,size.Width,size.Height);checkedModes++;}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","display-mode-check.json"),new JavaScriptSerializer().Serialize(new{passed=true,checkedModes=checkedModes,virtualDisplays=displays.Count,activeVirtualDisplays=displays.Count(d=>d.Attached),physicalDisplays=physical.Select(s=>new{s.DeviceName,bounds=s.Bounds.ToString()}).ToArray()}));}
 [DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out Native.Point point);
 [StructLayout(LayoutKind.Sequential)]struct MouseInput {public int X,Y;public uint Data,Flags,Time;public IntPtr Extra;}
 [StructLayout(LayoutKind.Sequential)]struct Input {public uint Type;public MouseInput Mouse;}
 [DllImport("user32.dll")]static extern uint SendInput(uint count,Input[] inputs,int size);
 [StructLayout(LayoutKind.Explicit,Size=40)]struct KeyInput {[FieldOffset(0)]public uint Type;[FieldOffset(8)]public ushort Key;[FieldOffset(12)]public uint Flags;}
 [DllImport("user32.dll",EntryPoint="SendInput")]static extern uint KeyEvents(uint count,KeyInput[] inputs,int size);
 static void MovePointer(Point point){var all=SystemInformation.VirtualScreen;var input=new Input{Type=0,Mouse=new MouseInput{X=(point.X-all.X)*65535/(all.Width-1),Y=(point.Y-all.Y)*65535/(all.Height-1),Flags=0xC001}};if(SendInput(1,new[]{input},Marshal.SizeOf(typeof(Input)))!=1)throw new Exception("통합 검사 마우스 이벤트 생성 실패");}
 static List<object> results=new List<object>();
 static void Check(string name,bool passed,object detail){results.Add(new{name=name,passed=passed,detail=detail});if(!passed)throw new Exception("FAIL: "+name);}
 static void Wait(int milliseconds){var until=DateTime.UtcNow.AddMilliseconds(milliseconds);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(15);}}
 static Color Pixel(Point point){using(var bitmap=new Bitmap(1,1))using(var graphics=Graphics.FromImage(bitmap)){graphics.CopyFromScreen(point,Point.Empty,new Size(1,1));return bitmap.GetPixel(0,0);}}
 static bool CloseColor(Color a,Color b){return Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B)<50;}
 public static void Run(){string root=AppDomain.CurrentDomain.BaseDirectory;bool passed=false,integration=false;var forms=new List<Form>();DesktopSurface surface=null;var session=new VirtualSession();
  try{Check("x64 compositor",Environment.Is64BitProcess,null);Check("DEVMODE layout",Marshal.SizeOf(typeof(Displays.Mode))==220,Marshal.SizeOf(typeof(Displays.Mode)));
   foreach(var key in Layouts.Keys){var rs=Layouts.Create(key);Check(key+" covers display",rs.Sum(r=>r.W*r.H)==4,null);}
   Check("pointer coordinate mapping",PointerBridge.Map(new Point(210,120),new Rectangle(10,20,400,200),new Rectangle(4010,220,400,200))==new Point(4210,320),null);
   using(var ui=new MainForm()){ui.Show();Wait(300);using(var bitmap=new Bitmap(ui.Width,ui.Height)){ui.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(root,"evidence","virtual-controller-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".png"));}ui.Close();}
   if(Environment.CommandLine.Contains("--full")){Check("actual virtual displays present",VirtualSession.Ready,Displays.Virtual().Count);integration=true;var target=Screen.AllScreens.Where(s=>!Displays.Virtual().Any(v=>v.Name==s.DeviceName)).ElementAt(Environment.CommandLine.Contains("--target-second")?1:0).Bounds;
    foreach(var key in Layouts.Keys){session.Start(target,Layouts.Create(key),key=="grid");Wait(900);var active=Displays.Virtual().Where(s=>s.Attached).ToList();Check(key+" actual active monitor count",active.Count==Layouts.Create(key).Count,active.Select(s=>new{s.Name,s.Mode.X,s.Mode.Y,s.Mode.Width,s.Mode.Height,s.Mode.Frequency}).ToArray());
     if(key=="grid"){
      var expected=new[]{Color.FromArgb(205,65,90),Color.FromArgb(50,135,220),Color.FromArgb(55,175,105),Color.FromArgb(220,170,60)};
      for(int i=0;i<session.Views.Count;i++){var v=session.Views[i];var f=new Form{AutoScaleMode=AutoScaleMode.None,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Bounds=v.Source,BackColor=expected[i],TopMost=true,ShowInTaskbar=false};f.Show();Native.SetWindowPos(f.Handle,new IntPtr(-1),v.Source.X,v.Source.Y,v.Source.Width,v.Source.Height,0x210);forms.Add(f);}Wait(700);for(int reposition=0;reposition<forms.Count;reposition++){var area=session.Views[reposition].Source;Native.SetWindowPos(forms[reposition].Handle,new IntPtr(-1),area.X,area.Y,area.Width,area.Height,0x210);}Wait(700);Check("test source windows retain source bounds",forms.Select((f,i)=>f.Bounds==session.Views[i].Source).All(x=>x),forms.Select(f=>f.Bounds.ToString()).ToArray());
      var samples=session.Views.Select(v=>Pixel(new Point(v.Destination.X+35,v.Destination.Y+35))).ToArray();Check("actual virtual desktops visible on physical display",samples.Select((c,i)=>CloseColor(c,expected[i])).All(b=>b),samples.Select(c=>c.ToString()).ToArray());
      using(var shot=new Bitmap(session.OutputBounds.Width,session.OutputBounds.Height))using(var graphics=Graphics.FromImage(shot)){graphics.CopyFromScreen(session.OutputBounds.Location,Point.Empty,shot.Size);shot.Save(Path.Combine(root,"evidence","actual-virtual-desktops-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".png"));}
      var first=session.Views[0];if(!Environment.CommandLine.Contains("--render-bench")){MovePointer(new Point(first.Destination.X+200,first.Destination.Y+200));Wait(50);session.Bridge.VerifiedProjections.Clear();MovePointer(new Point(first.Destination.X+60,first.Destination.Y+60));Wait(80);Check("physical pointer reaches virtual desktop",session.Bridge.VerifiedProjections.Any(p=>first.Source.Contains(p)),session.Bridge.VerifiedProjections.Select(p=>p.ToString()).ToArray());
      var field=new TextBox{Location=new Point(20,70),Size=new Size(250,32)};forms[0].Controls.Add(field);Wait(100);
      for(int clickAttempt=0;clickAttempt<3&&!field.Focused;clickAttempt++){MovePointer(new Point(first.Destination.X+40,first.Destination.Y+85));Wait(120);SendInput(2,new[]{new Input{Mouse=new MouseInput{Flags=2}},new Input{Mouse=new MouseInput{Flags=4}}},Marshal.SizeOf(typeof(Input)));Wait(150);}Check("click focuses input on virtual desktop",field.Focused,null);
      KeyEvents(2,new[]{new KeyInput{Type=1,Key=0x4D},new KeyInput{Type=1,Key=0x4D,Flags=2}},Marshal.SizeOf(typeof(KeyInput)));Wait(50);Check("keyboard reaches virtual desktop",string.Equals(field.Text,"m",StringComparison.OrdinalIgnoreCase),new{characters=field.Text.Length});
      forms[0].WindowState=FormWindowState.Maximized;Wait(250);Native.Rect maximized;Native.GetWindowRect(forms[0].Handle,out maximized);Check("maximize stays inside one virtual monitor",first.Source.Contains(new Point((maximized.Left+maximized.Right)/2,(maximized.Top+maximized.Bottom)/2))&&maximized.Box.Width<=first.Source.Width+20&&maximized.Box.Height<=first.Source.Height+20,maximized.Box.ToString());
      }var nextMonitor=Screen.AllScreens.First(s=>!Displays.Virtual().Any(v=>v.Name==s.DeviceName)&&s.Bounds!=session.OutputBounds);var groupRight=session.Views.Max(v=>v.Source.Right);Check("split group immediately left of monitor 2",(groupRight==nextMonitor.Bounds.Left||session.Views.Min(v=>v.Source.Left)==nextMonitor.Bounds.Right),new{splitRight=groupRight,monitor2Left=nextMonitor.Bounds.Left});
      if(!Environment.CommandLine.Contains("--render-bench")){Native.Point entered=new Native.Point();for(int attempt=0;attempt<3;attempt++){MovePointer(new Point(nextMonitor.Bounds.Left+20,nextMonitor.Bounds.Top+40));Wait(150);GetCursorPos(out entered);if(nextMonitor.Bounds.Contains(new Point(entered.X,entered.Y)))break;}Check("pointer enters monitor 2 without returning to split",nextMonitor.Bounds.Contains(new Point(entered.X,entered.Y)),new{x=entered.X,y=entered.Y});
      }var cpu=System.Diagnostics.Process.GetCurrentProcess();var startCpu=cpu.TotalProcessorTime.TotalMilliseconds;var startPerView=session.PerViewFrames;ulong startReceived=session.Received;ulong startFrames=session.Frames;var watch=System.Diagnostics.Stopwatch.StartNew();int updates=0;using(var timer=new Timer{Interval=16}){timer.Tick+=delegate{updates++;for(int fi=0;fi<forms.Count;fi++)forms[fi].BackColor=Color.FromArgb((updates*7+fi*41)%220+20,(updates*11+fi*29)%220+20,(updates*13+fi*17)%220+20);};timer.Start();Wait(2200);timer.Stop();}double elapsed=watch.Elapsed.TotalSeconds;var metrics=new{perView=session.PerViewFrames.Select((value,index)=>value-startPerView[index]).ToArray(),seconds=elapsed,received=(long)(session.Received-startReceived),frames=(long)(session.Frames-startFrames),framesPerViewPerSecond=(session.Frames-startFrames)/4.0/elapsed,processCpuCorePercent=(cpu.TotalProcessorTime.TotalMilliseconds-startCpu)/(elapsed*10),animatedUpdates=updates,errors=session.RenderErrors};if(!Environment.CommandLine.Contains("--compat-output")){Check("GPU output delivers live frames without errors",metrics.frames>8&&metrics.errors.All(e=>e==0),metrics);File.WriteAllText(Path.Combine(root,"evidence","performance-report.json"),new JavaScriptSerializer().Serialize(new{recordedAt=DateTime.UtcNow.ToString("o"),scope="2.2-second synthetic GDI color animation. Not a game/video benchmark or before-after comparison.",smoothnessTargetMet=metrics.framesPerViewPerSecond>=30,metrics=metrics}));}else{var delaySamples=new List<double>();for(int n=0;n<12;n++){var color=Color.FromArgb(30+n*15,80,150);foreach(var f in forms){f.BackColor=color;f.Update();}var delay=System.Diagnostics.Stopwatch.StartNew();bool matched=false;while(delay.ElapsedMilliseconds<500){Wait(2);if(session.Views.All(v=>CloseColor(Pixel(new Point(v.Destination.X+35,v.Destination.Y+35)),color))){matched=true;break;}}if(!matched)throw new Exception("DWM live refresh failed");delaySamples.Add(delay.Elapsed.TotalMilliseconds);}Check("single DWM surface live pixel response",true,new{latenciesMs=delaySamples,averageMs=delaySamples.Average(),benchmark=metrics});}
      foreach(var f in forms)f.Close();forms.Clear();
     }
     session.Stop();Wait(300);}
    Check("restore virtual displays after split",!File.Exists(Path.Combine(root,"data","virtual-recovery.json")),null);
   }
   passed=true;
  }finally{if(surface!=null)surface.Dispose();session.Stop();foreach(var f in forms)f.Close();Directory.CreateDirectory(Path.Combine(root,"evidence"));File.WriteAllText(Path.Combine(root,"evidence","virtual-test-report.json"),new JavaScriptSerializer().Serialize(new{recordedAt=DateTime.UtcNow.ToString("o"),passed=passed,virtualMonitorIntegration=integration,checks=results,driverReady=VirtualSession.Ready}));}
 }
}
}
